
const base64Db = "";

/* --- Helper: Parse XML from script block --- */
function parseXMLFromBase64(b64) {
  const xmlText = atob(b64); // decode Base64 → XML text
  return new DOMParser().parseFromString(xmlText, "application/xml");
}

/* --- Read xml, fill dropdown --- */
const xmlDoc = parseXMLFromBase64(base64Db);
/* --- Helper: Parse XML from script block --- */
function parseXMLFromScript() {
  const xmlText = document.getElementById('pumpXML').textContent.trim();
  return new DOMParser().parseFromString(xmlText, 'application/xml');
}


function getPumpModels() {
  return Array.from(xmlDoc.getElementsByTagName('PumpModel')).map(pm => {
    const name = pm.getAttribute('name');
    const baseRpmNode = pm.querySelector('Specifications > Base_RPM');
    const baseRpm = baseRpmNode ? parseFloat(baseRpmNode.textContent) : null;
    const baseDNode = pm.querySelector('Specifications > D_max');
    const baseD = baseDNode ? parseFloat(baseDNode.textContent) : null;
    const MinDNode = pm.querySelector('Specifications > D_min');
    const MinD = MinDNode ? parseFloat(MinDNode.textContent) : null;  
    const dataPoints = Array.from(pm.querySelectorAll('PerformanceData > DataPoint')).map(dp => ({
      gpm: parseFloat(dp.getElementsByTagName('GPM')[0].textContent),
      head_m: parseFloat(dp.getElementsByTagName('M')[0].textContent),
      kw: parseFloat(dp.getElementsByTagName('KW')[0].textContent)
    }));
    return { name, baseRpm, baseD, MinD, dataPoints, xmlNode: pm };
  });
}

const pumps = getPumpModels();

function populateDropdown() {
  const sel = document.getElementById('pumpSelect');
  sel.innerHTML = '<option value="">-- choose pump --</option>';
  const sorted = [...pumps].sort((a, b) => a.name.localeCompare(b.name));
  pumps.forEach(p => {
    const opt = document.createElement('option');
    opt.value = p.name;
    opt.textContent = p.name;
    sel.appendChild(opt);
  });
}
populateDropdown();

/* --- When pump changes --- */
function onPumpChange() {
  const sel = document.getElementById('pumpSelect');
  const name = sel.value;
  if (!name) {
    document.getElementById('inputSection').style.display = 'none';
    document.getElementById('baseInfo').style.display = 'none';
    return;
  }

  const pump = pumps.find(p => p.name === name);
  document.getElementById('inputSection').style.display = 'block';
  document.getElementById('baseInfo').style.display = 'block';
  document.getElementById('baseRpmText').textContent = pump.baseRpm ? pump.baseRpm.toFixed(0) + ' RPM' : '—';
  const newRPM = parseFloat(document.getElementById('inputSpeed').value);
  document.getElementById('baseRpmLabel').textContent = newRPM;
  //document.getElementById('baseRpmLabel').textContent = pump.baseRpm ? pump.baseRpm.toFixed(0) + ' RPM' : 'base RPM';
  const impSize = pump.MinD + " mm - " + pump.baseD + " mm";
  document.getElementById('impeller_size').textContent = impSize ? impSize : '—';
  // curve range (min and max GPM at base RPM)
  const gpmList = pump.dataPoints.map(d => d.gpm);
  const headList = pump.dataPoints.map(d => d.head_m);
  const min = Math.min(...gpmList);
  const max = Math.max(...gpmList);
  const minh = Math.min(...headList);
  const maxh = Math.max(...headList);
  document.getElementById('curveRange').textContent = `${(min).toFixed(2)} — ${(max).toFixed(2)} GPM`;
  document.getElementById('headRange').textContent = `${(maxh * 0.0981).toFixed(2)} — ${(minh * 0.0981).toFixed(2)} bar`;
}

function interpolateHead(flow, head, flow_p) {
  if (flow_p <= flow[0]) {    
    return { head_m: head[0], note: 'below_range' };
  }
  if (flow_p >= flow[flow.length - 1]) {
    return { head_m: head[flow.length - 1], note: 'above_range' };
  }

  for (let i = 0; i < flow.length - 1; i++) {
    const a = flow[i], b = flow[i + 1];
    if (flow_p >= a && flow_p <= b) {
      const t = (flow_p - a) / (b - a);
      const head_m = head[i] + t * (head[i + 1] - head[i]);      
      return head_m;
    }
  }
}

function correctedD(flowBase, headBase, kwBase, flow_p, head_p, D_min, D_max, D_ref, ratioRPM) {
  const tol = 0.1; 
  let lo = D_min, hi = D_max;
  let bestD = D_ref;
  let bestErr = Infinity;
  let iterations = 0;
  while (iterations < 40) {
    const mid = (lo + hi)/2;    
    const D_ratio = mid / D_max; 
    const scaledFlow = flowBase.map(f => f * D_ratio * ratioRPM);
    const scaledHead = headBase.map(h => h * Math.pow(D_ratio,2) * Math.pow(ratioRPM,2));
    const interp = interpolateHP(scaledFlow, scaledHead, kwBase, flow_p);
    const h_at_mid = interp.head_m;
    const err = h_at_mid - head_p;
    if (Math.abs(err) < Math.abs(bestErr)) {
      bestErr = err;
      bestD = mid;
    }
    if (Math.abs(err) <= tol) {      
      return mid;
    }
    if (h_at_mid < head_p) {
      lo = mid;
    } else {
      hi = mid;
    }
    iterations++;    
  }
  if (Math.abs(bestErr) > tol) {
    console.warn ('correctedDBinary: best error', bestErr);
  }
  return bestD;
}

function interpolateHP(flow, head, kw, flow_p) {
  if (flow_p <= Math.min(...flow)) {
    return { head_m: head[0], kw_p: kw[0], note: 'below_range' };
  }
  if (flow_p >= Math.max(...flow)) {
    return { head_m: head[flow.length - 1], kw_p: kw[flow.length - 1], note: 'above_range' };
  }

  for (let i = 0; i < flow.length - 1; i++) {
    const a = flow[i], b = flow[i + 1];
    if (flow_p >= a && flow_p <= b) {
      const t = (flow_p - a) / (b - a);
      const head_m = head[i] + t * (head[i + 1] - head[i]);
      const kw_p = kw[i] + t * (kw[i + 1] - kw[i]);
      return { head_m, kw_p, note: 'interpolated' };
    }
  }  
}

/* --- Utility: linear interpolation for KW (and head if needed) vs GPM --- */
function interpAtFlow(dataPoints, flow) {
  // dataPoints: array sorted by gpm ascending (should be from XML)
  const sorted = dataPoints.slice().sort((a,b) => a.gpm - b.gpm);
  if (flow <= sorted[0].gpm) return { head_m: sorted[0].head_m, kw: sorted[0].kw, note: 'below_range' };
  if (flow >= sorted[sorted.length-1].gpm) return { head_m: sorted[sorted.length-1].head_m, kw: sorted[sorted.length-1].kw, note: 'above_range' };

  for (let i=0;i<sorted.length-1;i++){
    const a = sorted[i], b = sorted[i+1];
    if (flow >= a.gpm && flow <= b.gpm) {
      const t = (flow - a.gpm) / (b.gpm - a.gpm);
      const head_m = a.head_m + t*(b.head_m - a.head_m);
      const kw = a.kw + t*(b.kw - a.kw);
      return { head_m, kw, note: 'interpolated' };
    }
  }
  // fallback
  return { head_m: sorted[0].head_m, kw: sorted[0].kw, note: 'fallback' };
}


function metersToFeet(m){ return m * 3.28084; }
function bartometer(b){ return b / 0.0981;  }

function computeEfficiency(q_gpm, head_m, power_kw){
  const head_ft = metersToFeet(head_m);
  const hydraulic_hp = (q_gpm * head_ft) / 3960; // hydraulic horsepower
  const hydraulic_kw = hydraulic_hp * 0.746; // convert hp -> kW
  if (power_kw <= 0) return NaN;
  return (hydraulic_kw / power_kw) * 100;
}

function plotPumpCurve(flow, head, power, rflow, rhead, rpower) {
    const canvas = document.getElementById('pumpChart');
    if (!canvas) {
        console.error("Canvas element with id 'pumpChart' not found.");
        return;
    }
    const ctx = canvas.getContext('2d');

    // 1. Efficient coordinate mapping
    const mapToXY = (xArr, yArr) => {
        const result = [];
        const len = Math.min(xArr.length, yArr.length);
        for (let i = 0; i < len; i++) {
            result.push({ x: xArr[i], y: yArr[i] });
        }
        return result;
    };

    // Calculate efficiency values (Flow: GPM, Head: meters, Power: kW)
    const effArray = flow.map((f, i) => {
        const p = power[i];
        const h = head[i];
        if (!p || p === 0) return 0;
        const eff = ((f * h) / (p * 1618)) * 100; 
        return Math.min(Math.max(eff, 0), 100);
    });

    if (window.myPumpChart) {
        window.myPumpChart.destroy();
        window.myPumpChart = null;
    }

    window.myPumpChart = new Chart(ctx, {
        type: 'line', // Changed to line with linear scale for significantly faster rendering
        data: {
            datasets: [
                {
                    label: 'Head',
                    data: mapToXY(flow, head),
                    borderColor: 'blue',
                    borderWidth: 2,
                    pointRadius: 0,
                    tension: 0.3,
                    yAxisID: 'yHead'
                },
                {
                    label: 'Efficiency (%)',
                    data: mapToXY(flow, effArray),
                    borderColor: 'green',
                    borderWidth: 2,
                    pointRadius: 0,
                    tension: 0.3,
                    yAxisID: 'yPercent'
                },
                {
                    label: 'Power',
                    data: mapToXY(flow, power),
                    borderColor: 'red',
                    borderWidth: 2,
                    pointRadius: 0,
                    tension: 0.3,
                    yAxisID: 'yPower'
                },
                {
                    label: 'Rated Point',
                    data: [{ x: rflow, y: rhead }],
                    backgroundColor: 'rgb(255, 99, 132)',
                    borderColor: 'darkred',
                    pointRadius: 6,
                    yAxisID: 'yHead'
                }
            ]
        },
        options: {
            responsive: true,
            maintainAspectRatio: true, // Fixed chart sizing issue
            animation: false,          // Disables redundant animation render loops
            interaction: {
                mode: 'nearest',       // Fast performance interaction mode
                intersect: false
            },
            scales: {
                x: {
                    type: 'linear',
                    position: 'bottom',
                    title: { display: true, text: 'Flow Rate' }
                },
                yHead: {
                    type: 'linear',
                    display: true,
                    position: 'left',
                    title: { display: true, text: 'Head' },
                    min: 0
                },
                yPercent: {
                    type: 'linear',
                    display: true,
                    position: 'right',
                    title: { display: true, text: 'Efficiency (%)' },
                    min: 0,
                    max: 100,
                    grid: { drawOnChartArea: false }
                },
                yPower: {
                    type: 'linear',
                    display: true,
                    position: 'right',
                    title: { display: true, text: 'Power' },
                    min: 0,
                    grid: { drawOnChartArea: false }
                }
            },
            plugins: {
                annotation: {
                    annotations: {
                        ratedFlowLine: {
                            type: 'line',
                            xMin: rflow,
                            xMax: rflow,
                            borderColor: 'rgb(255, 99, 132)',
                            borderWidth: 2,
                            borderDash: [6, 6],
                            label: {
                                display: true,
                                content: `100% Flow (${Number(rflow)} gpm)`,
                                position: 'center',
                                rotation: -90,
                                xAdjust: -12,
                                textAlign: 'start',
                                color: 'rgb(255, 99, 132)',
                                backgroundColor: 'transparent',
                                padding: 0,
                                font: { size: 11, weight: 'bold' }
                            }
                        }
                    }
                }
            }
        },
        plugins: [Chart.registry.getPlugin('annotation')]
    });
}

function predict() {
  const sel = document.getElementById('pumpSelect');
  const pumpName = sel.value;
  if (!pumpName) { alert('Please choose a pump model.'); return; }
  const pump = pumps.find(p => p.name === pumpName);
  const baseRPM = pump.baseRpm;
  if (!baseRPM) { alert('Base RPM missing for this pump in XML'); return; }

  const q_input = parseFloat(document.getElementById('inputFlow').value);
  const h_input = bartometer(parseFloat(document.getElementById('inputHead').value));
  const newRPM = parseFloat(document.getElementById('inputSpeed').value);

  if (isNaN(q_input) || isNaN(h_input) || isNaN(newRPM)) {
    alert('Please enter Flow (GPM), Head (m) and New Speed (RPM).');
    return;
  }
  resetResults();
  
  const interp = interpAtFlow(pump.dataPoints, q_input);
  const kw_base_from_curve = interp.kw;
  const head_from_curve = interp.head_m;
  const ratioRPM = newRPM / baseRPM;
  const H_Ratio = (h_input / head_from_curve) || 1;
  const D_ref = pump.baseD * Math.sqrt(H_Ratio); 

  let t_flow = pump.dataPoints.map(dp => dp.gpm);
  let t_head = pump.dataPoints.map(dp => dp.head_m);
  let t_kw = pump.dataPoints.map(dp => dp.kw);  
  let D = 0.0;
  let D_Status = "OK";

  let p_flow =[];
  let p_head = [];
  let p_kw = [];

  for (i=0;i < t_flow.length;i++){
    p_flow[i] = t_flow[i];
    p_head[i] = t_head[i];
    p_kw[i] = t_kw[i];    
  } 

  D = correctedD(t_flow, t_head, t_kw, q_input, h_input, pump.MinD, pump.baseD, D_ref, ratioRPM);

  const D_Ratio = D / pump.baseD;
  
  for (i=0;i < p_flow.length;i++){
    p_flow[i] = p_flow[i] * D_Ratio * ratioRPM;
    p_head[i] = p_head[i] * Math.pow(D_Ratio,2) * Math.pow(ratioRPM,2);
    p_kw[i] = p_kw[i] * Math.pow(D_Ratio,3) * Math.pow(ratioRPM,3);
  }  

  const newScaled = interpolateHP(p_flow, p_head, p_kw, q_input);
  let H_curve_newRPM = newScaled.head_m;
  let P_curve_newRPM = newScaled.kw_p;
  let H_150 = 0.00;
  let P_150 = 0.00;
  const interp150 = interpolateHP(p_flow, p_head, p_kw, q_input*1.5);
  if (interp150.note === "below_range" || interp150.note === "above_range")
  {
    H_150 = 0.00;
    P_150 = 0.00;

  } else{
      H_150 = interp150.head_m;
      P_150 = interp150.kw_p;
  }  
  
  const eff_new = computeEfficiency(q_input*1.5,H_150, P_150);
  const eff_base = computeEfficiency(q_input, H_curve_newRPM, P_curve_newRPM);

  let h_new = H_curve_newRPM;
  let p_new = P_curve_newRPM;
  let Q_equiv = q_input;
  let q_new = q_input;
  
  const gpmList = pump.dataPoints.map(d => d.gpm);
  const minG = Math.min(...gpmList);
  const maxG = Math.max(...gpmList);
  const minG_new = minG * ratioRPM * D_Ratio;
  const maxG_new = maxG * ratioRPM * D_Ratio;
  const inRange = (Q_equiv >= minG_new - 1e-6) && (Q_equiv <= maxG_new + 1e-6); 

  const H_err = h_input - H_curve_newRPM;

  if (Math.abs(H_err) > 1){
    if(h_input < H_curve_newRPM){
      D_Status = "Below the range";      
    }
    else{
      D_Status = "Above the range";
    }
  }

  const statusEl = document.getElementById('statusMsg');
  statusEl.innerHTML = '';
  if (interp.note === 'below_range') {
    statusEl.innerHTML += `<div class="warn">Note: the entered Flow (${q_input.toFixed(2)} GPM) is below the pump curve range (${minG.toFixed(2)}—${maxG.toFixed(2)} GPM).</div>`;    
    console.log("below_range");
  } else if(interp.note === 'above_range'){
    statusEl.innerHTML += `<div class="warn">Note: the entered Flow (${q_input.toFixed(2)} GPM) is above the pump curve range (${minG.toFixed(2)}—${maxG.toFixed(2)} GPM).</div>`;
    console.log("above_range");
  } else if(D_Status === 'Above the range'){
    statusEl.innerHTML += `<div class="warn">Note: the entered Pressure (${(h_input*0.0981).toFixed(2)} bar) is above the pump curve range (${minG.toFixed(2)}—${maxG.toFixed(2)} GPM).</div>`;
    console.log("Above the range");
  } else if (D_Status === 'Below the range') {
    statusEl.innerHTML += `<div class="warn">Note: the entered Pressure (${(h_input*0.0981).toFixed(2)} bar) is below the pump curve range (${minG.toFixed(2)}—${maxG.toFixed(2)} GPM).</div>`;
    console.log("Below the range");
  } else {
    statusEl.innerHTML += `<div class="ok">The calculated impeller diameter is ${D.toFixed(0)} mm.</div>`;
    document.getElementById('results').style.display = 'block';
    document.getElementById('pump_model').textContent = `${pumpName}`;
    document.getElementById('res_q_base').textContent = `${q_input.toFixed(2)} GPM`;
    document.getElementById('res_h_base').textContent = `${H_curve_newRPM.toFixed(2)} m / ${(H_curve_newRPM * 0.0981).toFixed(2)} bar`;
    document.getElementById('res_p_base').textContent = `${P_curve_newRPM.toFixed(3)} kW / ${(P_curve_newRPM / 0.746).toFixed(3)} hp`;
    document.getElementById('res_eff_base').textContent = isNaN(eff_base) ? 'N/A' : eff_base.toFixed(2) + ' %';

    document.getElementById('res_q_new').textContent = H_150 === 0 || P_150 === 0 ? "N/A" : `${q_input*1.5.toFixed(2)} GPM`;
    document.getElementById('res_h_new').textContent = H_150 === 0 ? "N/A" : `${H_150.toFixed(2)} m / ${(H_150 * 0.0981).toFixed(2)} bar`;
    document.getElementById('res_p_new').textContent = P_150 === 0 ? "N/A" : `${P_150.toFixed(2)} kW / ${(P_150 / 0.746).toFixed(2)} hp`;
    document.getElementById('res_eff_new').textContent = isNaN(eff_new) ? 'N/A' : eff_new.toFixed(2) + ' %';
    
    plotPumpCurve(p_flow, p_head, q_input, H_curve_newRPM);

  }
  const curveCheckEl = document.getElementById('curveCheck');
  document.getElementById('curveCheckCard').style.display = 'block';

  const statusText = inRange ? "In Range" : "Out of Range";
  const statusClass = inRange ? "ok" : "warn";
  const note = inRange ? "" : "Operating outside the curve is not recommended.";

  curveCheckEl.innerHTML = `
  <table border="1" cellpadding="6" style="border-collapse: collapse; width:100%; text-align:center;">
    <thead>
      <tr>
        <th>Predicted Flow (GPM)</th>
        <th>Curve Range (GPM)</th>
        <th>Status</th>
        <th>Note</th>
      </tr>
    </thead>
    <tbody>
      <tr>
        <td>${q_input.toFixed(2)}</td>
        <td>${minG_new.toFixed(2)} — ${maxG_new.toFixed(2)}</td>
        <td class="${statusClass}"><strong>${statusText}</strong></td>
        <td>${note}</td>
      </tr>
    </tbody>
  </table>
  `;  
  curveCheckEl.innerHTML += `<div style="margin-top:8px;"><strong>Summary:</strong><br> Rated Flow=${q_input.toFixed(2)} GPM, Rated Pressure=${H_curve_newRPM.toFixed(2)} m, Power at 100%=${P_curve_newRPM.toFixed(3)} kW, Power at 150%=${P_150.toFixed(3)} kW → at ${newRPM} RPM.</div>`;  
}

function resetResults(){
  document.getElementById('results').style.display = 'none';
  document.getElementById('statusMsg').innerHTML = '';
  document.getElementById('curveCheckCard').style.display = 'none';
  if (window.myPumpChart) {
    window.myPumpChart.destroy();
    window.myPumpChart = null;
  }
}

onPumpChange();

